while True:
    user_input = input("Enter a port number: ")
    try:
        port = int(user_input)
        if 1 <= port <= 65535:
            print(f"Port {port} accepted.")
            break
        else:
            print("Port out of range (1‑65535).")
    except ValueError:
        print("Invalid input; must be a number.")
